// Deterministically pack complete UTF-8-framed context sections.

function invalid(message) {
  throw new Error(message);
}

function validate(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) invalid('maxBytes must be a nonnegative safe integer');
  if (!Array.isArray(sections)) invalid('sections must be an array');

  const ids = new Set();
  const entries = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) invalid('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) invalid('section must be an object');
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0) invalid('section id must be a nonempty string');
    if (typeof text !== 'string') invalid('section text must be a string');
    if (!Number.isSafeInteger(priority) || priority < 0) invalid('section priority must be a nonnegative safe integer');
    if (typeof required !== 'boolean') invalid('section required must be a boolean');
    if (ids.has(id)) invalid('section ids must be unique');
    ids.add(id);
    const frame = `### ${JSON.stringify(id)}\n${text}\n`;
    entries.push({ id, required, priority, index, frame, bytes: Buffer.byteLength(frame, 'utf8') });
  }
  return entries;
}

export function packContext(sections, maxBytes) {
  const entries = validate(sections, maxBytes);
  const included = [];
  const frames = [];
  let bytes = 0;

  for (const entry of entries) {
    if (!entry.required) continue;
    if (bytes + entry.bytes > maxBytes) invalid('required sections exceed maxBytes');
    bytes += entry.bytes;
    frames.push(entry.frame);
    included.push(entry.id);
  }

  const omitted = new Set();
  const optional = entries.filter((entry) => !entry.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  for (const entry of optional) {
    if (bytes + entry.bytes <= maxBytes) {
      bytes += entry.bytes;
      frames.push(entry.frame);
      included.push(entry.id);
    } else {
      omitted.add(entry.id);
    }
  }

  return { text: frames.join(''), bytes, included, omitted: entries.filter((entry) => omitted.has(entry.id)).map((entry) => entry.id) };
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('expected exactly one input JSON file');
  const fs = require('node:fs');
  const input = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
  const result = packContext(input.sections, input.maxBytes);
  process.stdout.write(`${JSON.stringify(result)}\n`);
}

if (process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
  try {
    runCli();
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

