import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = 'x', priority = 0, required = false) => ({ id, text, priority, required });
const frame = (id, text) => `### ${JSON.stringify(id)}\n${text}\n`;

test('validates every field and every entry before considering budget', () => {
  const invalidSections = [
    null, [], 'section', { id: '', text: 'x', priority: 0, required: false },
    { id: 1, text: 'x', priority: 0, required: false },
    { id: 'x', text: 1, priority: 0, required: false },
    { id: 'x', text: 'x', priority: -1, required: false },
    { id: 'x', text: 'x', priority: 1.5, required: false },
    { id: 'x', text: 'x', priority: Number.MAX_SAFE_INTEGER + 1, required: false },
    { id: 'x', text: 'x', priority: 0, required: 'false' },
    { id: 'x', text: 'x', priority: 0 },
  ];
  for (const value of invalidSections) assert.throws(() => packContext([value], 0), Error);
  for (const budget of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '1', null]) {
    assert.throws(() => packContext([], budget), Error);
  }
  assert.throws(() => packContext([section('valid'), { id: 'bad', text: 1, priority: 0, required: false }], 0), Error);
  const sparse = [section('first'), section('second')]; delete sparse[1];
  assert.throws(() => packContext(sparse, 0), Error);
  assert.throws(() => packContext({ 0: section('x'), length: 1 }, 0), Error);
});

test('uses exact string IDs and preserves special IDs without mutation', () => {
  const ids = ['A', 'a', '__proto__', 'hasOwnProperty', 'space id', '雪\n\u0000'];
  const input = ids.map((id, index) => section(id, `text-${index}`, index, index === 0));
  const before = structuredClone(input);
  const result = packContext(input, 10000);
  assert.deepEqual(result.included, ids);
  assert.deepEqual(result.omitted, []);
  assert.equal(result.text, input.map(({ id, text }) => frame(id, text)).join(''));
  assert.deepEqual(input, before);
  assert.throws(() => packContext([section('A'), section('a'), section('A')], 0), Error);
});

test('required ordering, optional priority, ties, and skip-and-continue are deterministic', () => {
  const requiredOne = section('required-late', 'r', 0, true);
  const requiredTwo = section('required-early', 'q', 99, true);
  const large = section('large', 'x'.repeat(60), 10);
  const tiedFirst = section('tied-first', 'a', 5);
  const tiedSecond = section('tied-second', 'b', 5);
  const low = section('low', 'c', 1);
  const requiredBytes = Buffer.byteLength(frame(requiredOne.id, requiredOne.text) + frame(requiredTwo.id, requiredTwo.text));
  const budget = requiredBytes + Buffer.byteLength(frame(tiedFirst.id, tiedFirst.text)) + Buffer.byteLength(frame(tiedSecond.id, tiedSecond.text)) + Buffer.byteLength(frame(low.id, low.text));
  const result = packContext([large, requiredOne, tiedFirst, requiredTwo, tiedSecond, low], budget);
  assert.deepEqual(result.included, ['required-late', 'required-early', 'tied-first', 'tied-second', 'low']);
  assert.deepEqual(result.omitted, ['large']);
  assert.equal(result.bytes, Buffer.byteLength(result.text, 'utf8'));
  assert.throws(() => packContext([section('one', 'x', 0, true), section('two', 'x', 0, true)], Buffer.byteLength(frame('one', 'x'))), Error);
});

test('UTF-8 framing is exact, exact fits work, and empty input is stable', () => {
  const id = '雪'; const text = 'é\n'; const exact = frame(id, text);
  const bytes = Buffer.byteLength(exact, 'utf8');
  assert.deepEqual(packContext([section(id, text)], bytes), { text: exact, bytes, included: [id], omitted: [] });
  assert.deepEqual(packContext([section(id, text)], bytes - 1), { text: '', bytes: 0, included: [], omitted: [id] });
  assert.deepEqual(packContext([], 0), { text: '', bytes: 0, included: [], omitted: [] });
  assert.deepEqual(packContext([], 123), { text: '', bytes: 0, included: [], omitted: [] });
});

function cli(args, options = {}) {
  return spawnSync(process.execPath, ['context-packet.js', ...args], { cwd: process.cwd(), encoding: 'utf8', ...options });
}

test('CLI has exact successful output and guarded errors', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    const good = join(directory, 'good.json');
    const input = { sections: [section('x', 'é', 0, true)], maxBytes: 100 };
    writeFileSync(good, JSON.stringify(input), 'utf8');
    const expected = `${JSON.stringify(packContext(input.sections, input.maxBytes))}\n`;
    const success = cli([good]);
    assert.equal(success.status, 0); assert.equal(success.stdout, expected); assert.equal(success.stderr, '');
    const bad = join(directory, 'bad.json'); writeFileSync(bad, '{not json', 'utf8');
    const overflow = join(directory, 'overflow.json'); writeFileSync(overflow, JSON.stringify({ sections: [section('r', 'x', 0, true)], maxBytes: 0 }), 'utf8');
    for (const args of [[], [good, good], [join(directory, 'missing.json')], [bad], [overflow]]) {
      const result = cli(args);
      assert.equal(result.status, 2); assert.equal(result.stdout, ''); assert.notEqual(result.stderr, '');
    }
  } finally { rmSync(directory, { recursive: true, force: true }); }
});

test('importing does not execute CLI', () => {
  const result = spawnSync(process.execPath, ['--input-type=module', '--eval', "import './context-packet.js'"], { cwd: process.cwd(), encoding: 'utf8' });
  assert.equal(result.status, 0); assert.equal(result.stdout, ''); assert.equal(result.stderr, '');
});

